func TestRingWithAttrsAndGroup(t *testing.T) {
	r, err := NewRing(1)
	if err != nil {
		t.Fatal(err)
	}

	h1 := r.WithAttrs(nil)
	if _, ok := h1.(*Ring); !ok {
		t.Error("WithAttrs returned a non-Ring handler")
	}

	h2 := r.WithGroup("testgroup")
